(* First-scan initialization *)
IF FirstScan THEN
    SV_104_01 := FALSE;
    PV_4712_02_Out := 6554;
    FirstScan := FALSE;
    RETURN;
END_IF;

(* Scale analog inputs from 4-20 mA to engineering units *)
PI_4712_01_Scaled := ((INT_TO_REAL(PI_4712_01_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0 + 0.0;
PICSA_4712_02_Scaled := ((INT_TO_REAL(PICSA_4712_02_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0 + 0.0;
TICSA_4750_03_Scaled := ((INT_TO_REAL(TICSA_4750_03_Raw) - 6554.0) / (32767.0 - 6554.0)) * 250.0 + 0.0;
HS_4750_01_Scaled := 1.0;

(* PI-4712.01 Alarm Logic *)
IF PI_4712_01_Scaled >= PI_4712_01_HH_SP THEN
    PI_4712_01_HH := TRUE;
    PI_4712_01_HH_Latch.S1 := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_HH_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_HH := FALSE;
    PI_4712_01_HH_Latch.S1 := FALSE;
END_IF;

IF PI_4712_01_Scaled >= PI_4712_01_H_SP THEN
    PI_4712_01_H := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_H_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_H := FALSE;
END_IF;

IF PI_4712_01_Scaled <= PI_4712_01_L_SP THEN
    PI_4712_01_L := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_L_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_L := FALSE;
END_IF;

IF PI_4712_01_Scaled <= PI_4712_01_LL_SP THEN
    PI_4712_01_LL := TRUE;
    PI_4712_01_LL_Latch.S1 := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_LL_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_LL := FALSE;
    PI_4712_01_LL_Latch.S1 := FALSE;
END_IF;

PI_4712_01_HH_Latch.R := PI_4712_01_HH_Ack AND NOT PI_4712_01_HH;
PI_4712_01_LL_Latch.R := PI_4712_01_LL_Ack AND NOT PI_4712_01_LL;
PI_4712_01_HH_Latch();
PI_4712_01_LL_Latch();

(* PICSA-4712.02 Alarm Logic *)
IF PICSA_4712_02_Scaled >= PICSA_4712_02_HH_SP THEN
    PICSA_4712_02_HH := TRUE;
    PICSA_4712_02_HH_Latch.S1 := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_HH_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_HH := FALSE;
    PICSA_4712_02_HH_Latch.S1 := FALSE;
END_IF;

IF PICSA_4712_02_Scaled >= PICSA_4712_02_H_SP THEN
    PICSA_4712_02_H := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_H_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_H := FALSE;
END_IF;

IF PICSA_4712_02_Scaled <= PICSA_4712_02_L_SP THEN
    PICSA_4712_02_L := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_L_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_L := FALSE;
END_IF;

IF PICSA_4712_02_Scaled <= PICSA_4712_02_LL_SP THEN
    PICSA_4712_02_LL := TRUE;
    PICSA_4712_02_LL_Latch.S1 := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_LL_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_LL := FALSE;
    PICSA_4712_02_LL_Latch.S1 := FALSE;
END_IF;

PICSA_4712_02_HH_Latch.R := PICSA_4712_02_HH_Ack AND NOT PICSA_4712_02_HH;
PICSA_4712_02_LL_Latch.R := PICSA_4712_02_LL_Ack AND NOT PICSA_4712_02_LL;
PICSA_4712_02_HH_Latch();
PICSA_4712_02_LL_Latch();

(* TICSA-4750.03 Alarm Logic *)
IF TICSA_4750_03_Scaled >= TICSA_4750_03_HH_SP THEN
    TICSA_4750_03_HH := TRUE;
    TICSA_4750_03_HH_Latch.S1 := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_HH_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_HH := FALSE;
    TICSA_4750_03_HH_Latch.S1 := FALSE;
END_IF;

IF TICSA_4750_03_Scaled >= TICSA_4750_03_H_SP THEN
    TICSA_4750_03_H := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_H_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_H := FALSE;
END_IF;

IF TICSA_4750_03_Scaled <= TICSA_4750_03_L_SP THEN
    TICSA_4750_03_L := TRUE;
ELSIF TICSA_4750_03_Scaled >= (TICSA_4750_03_L_SP + TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_L := FALSE;
END_IF;

IF TICSA_4750_03_Scaled <= TICSA_4750_03_LL_SP THEN
    TICSA_4750_03_LL := TRUE;
    TICSA_4750_03_LL_Latch.S1 := TRUE;
ELSIF TICSA_4750_03_Scaled >= (TICSA_4750_03_LL_SP + TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_LL := FALSE;
    TICSA_4750_03_LL_Latch.S1 := FALSE;
END_IF;

TICSA_4750_03_HH_Latch.R := TICSA_4750_03_HH_Ack AND NOT TICSA_4750_03_HH;
TICSA_4750_03_LL_Latch.R := TICSA_4750_03_LL_Ack AND NOT TICSA_4750_03_LL;
TICSA_4750_03_HH_Latch();
TICSA_4750_03_LL_Latch();

(* HS-4750.01 Alarm Logic *)
IF HS_4750_01_Scaled >= HS_4750_01_HH_SP THEN
    HS_4750_01_HH := TRUE;
    HS_4750_01_HH_Latch.S1 := TRUE;
ELSIF HS_4750_01_Scaled <= (HS_4750_01_HH_SP - HS_4750_01_Deadband) THEN
    HS_4750_01_HH := FALSE;
    HS_4750_01_HH_Latch.S1 := FALSE;
END_IF;

IF HS_4750_01_Scaled >= HS_4750_01_H_SP THEN
    HS_4750_01_H := TRUE;
ELSIF HS_4750_01_Scaled <= (HS_4750_01_H_SP - HS_4750_01_Deadband) THEN
    HS_4750_01_H := FALSE;
END_IF;

IF HS_4750_01_Scaled <= HS_4750_01_L_SP THEN
    HS_4750_01_L := TRUE;
ELSIF HS_4750_01_Scaled >= (HS_4750_01_L_SP + HS_4750_01_Deadband) THEN
    HS_4750_01_L := FALSE;
END_IF;

IF HS_4750_01_Scaled <= HS_4750_01_LL_SP THEN
    HS_4750_01_LL := TRUE;
    HS_4750_01_LL_Latch.S1 := TRUE;
ELSIF HS_4750_01_Scaled >= (HS_4750_01_LL_SP + HS_4750_01_Deadband) THEN
    HS_4750_01_LL := FALSE;
    HS_4750_01_LL_Latch.S1 := FALSE;
END_IF;

HS_4750_01_HH_Latch.R := HS_4750_01_HH_Ack AND NOT HS_4750_01_HH;
HS_4750_01_LL_Latch.R := HS_4750_01_LL_Ack AND NOT HS_4750_01_LL;
HS_4750_01_HH_Latch();
HS_4750_01_LL_Latch();

(* Pressure Control Loop - PICSA-4712.02 controls PV-4712.02 *)
PID_Error := PICSA_4712_02_Setpoint - PICSA_4712_02_Scaled;
PID_Integral := PID_Integral + (Ki * PID_Error);
IF PID_Integral > 100.0 THEN
    PID_Integral := 100.0;
ELSIF PID_Integral < 0.0 THEN
    PID_Integral := 0.0;
END_IF;
PID_Output := (Kp * PID_Error) + PID_Integral;
IF PID_Output > 100.0 THEN
    PID_Output := 100.0;
ELSIF PID_Output < 0.0 THEN
    PID_Output := 0.0;
END_IF;
PV_4712_02_Out := REAL_TO_INT(6554.0 + (PID_Output / 100.0) * (32767.0 - 6554.0));

(* Solenoid valve control based on hand switch *)
SV_104_01 := HS_4750_01;

(* Aggregate all alarm states for SCADA/HMI *)
System_Alarm :=
    PI_4712_01_HH_Latch.Q1 OR PI_4712_01_LL_Latch.Q1 OR
    PI_4712_01_H OR PI_4712_01_L OR
    PICSA_4712_02_HH_Latch.Q1 OR PICSA_4712_02_LL_Latch.Q1 OR
    PICSA_4712_02_H OR PICSA_4712_02_L OR
    TICSA_4750_03_HH_Latch.Q1 OR TICSA_4750_03_LL_Latch.Q1 OR
    TICSA_4750_03_H OR TICSA_4750_03_L OR
    HS_4750_01_HH_Latch.Q1 OR HS_4750_01_LL_Latch.Q1 OR
    HS_4750_01_H OR HS_4750_01_L;
